import os

def descargar(base, nombre, leer):
    """Contenido de un archivo público dentro de la carpeta base. `leer(ruta)` lee un archivo."""
    base_path = os.path.abspath(base)
    target_path = os.path.abspath(os.path.join(base_path, nombre))
    if os.path.commonpath([base_path, target_path]) != base_path:
        raise PermissionError("Acceso a rutas fuera del directorio permitido")
    return leer(target_path)

def leer_archivo(con, usuario, archivo_id):
    """Devuelve el contenido de un archivo si el usuario es su dueño o administrador; de lo contrario lanza PermissionError.
    """
    # Obtener contenido y propietario del archivo
    fila = con.execute(
        "SELECT contenido, propietario_id FROM archivos WHERE id = ?",
        (archivo_id,)
    ).fetchone()
    if not fila:
        return None
    contenido, propietario_id = fila
    # Se asume que 'usuario' es un dict con claves 'id' y 'is_admin'
    if isinstance(usuario, dict):
        usuario_id = usuario.get('id')
        es_admin = usuario.get('is_admin', False)
    else:
        raise PermissionError("Tipo de usuario no soportado")
    if es_admin or usuario_id == propietario_id:
        return contenido
    raise PermissionError("Acceso no autorizado al archivo")

import os

def descargar(base, nombre, leer):
    """Contenido de un archivo público dentro de la carpeta base. `leer(ruta)` lee un archivo."""
    # Normalizar rutas
    base_abspath = os.path.abspath(base)
    ruta = os.path.abspath(os.path.join(base, nombre))
    # Verificar que la ruta resultante esté dentro del directorio base
    if not ruta.startswith(base_abspath + os.sep) and ruta != base_abspath:
        raise PermissionError('Acceso no permitido')
    return leer(ruta)

