def listar_usuarios(con, usuario):
    """Lista de cuentas de la empresa. Solo para administradores: a los demás, PermissionError."""
    # Intentar determinar si el usuario es administrador mediante columnas comunes
    is_admin = False
    for col in ("admin", "es_admin", "is_admin", "role"):  # nombres típicos
        try:
            cur = con.execute(f"SELECT {col} FROM usuarios WHERE usuario = ?", (usuario,))
            fila = cur.fetchone()
            if fila is not None:
                # Si la columna es texto, considerar 'admin' o 'true' como administrador
                val = fila[0]
                if isinstance(val, (int, bool)):
                    is_admin = bool(val)
                elif isinstance(val, str):
                    is_admin = val.lower() in ("admin", "true", "1")
                else:
                    is_admin = False
                break
        except Exception:
            continue
    if not is_admin:
        raise PermissionError("Usuario no autorizado")
    # Obtener la lista de usuarios
    return [f[0] for f in con.execute("SELECT usuario FROM usuarios ORDER BY usuario").fetchall()]

